// ==UserScript==
// @name         Janitor Manuscript Dissolve
// @namespace    http://tampermonkey.net/
// @version      0.0.0
// @description  Carries the User Intervention Dissolve protocol onto JanitorAI proxy requests: one continuous manuscript, hidden interaction boundaries.
// @match        https://janitorai.com/*
// @match        https://*.janitorai.com/*
// @grant        none
// @run-at       document-start
// @sandbox      raw
// ==/UserScript==

// Generated by `npm run build:janitor` from janitor/ and src/. Do not edit by hand.

(function () {
'use strict';

// ---- janitor/shape.js ----
function isObject(value) {
  return typeof value === 'object' && value !== null;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}

// chat-shape-test: role + own content only, so Anthropic reads as chat → docs/modules/janitor-transport.md#chat-shape-adapter
function isCompletionMessageArray(messages) {
  if (!Array.isArray(messages) || messages.length === 0) return false;
  return messages.every((message) => {
    if (!isObject(message) || typeof message.role !== 'string') return false;
    return hasOwn(message, 'content');
  });
}

// alpha-shape-test: the four fields that mark Janitor's pre-assembly envelope → docs/modules/janitor-transport.md#chat-shape-adapter
function isJanitorAlphaRequestShape(node) {
  return Boolean(
    isObject(node)
      && isObject(node.userConfig)
      && isObject(node.chat)
      && Array.isArray(node.chatMessages)
      && typeof node.generateType === 'string',
  );
}

function modelNameFromContainer(container) {
  if (!isObject(container)) return '';
  if (typeof container.model === 'string') return container.model;
  if (typeof container.openAiModel === 'string') return container.openAiModel;
  if (Array.isArray(container.models)) {
    const first = container.models.find((model) => typeof model === 'string');
    if (first) return first;
  }
  return '';
}

// locate-request: envelope first, then the model-sibling walk; no responses shape → docs/modules/janitor-transport.md#chat-shape-adapter
function locateCompletionRequest(root) {
  if (!isObject(root)) return null;
  if (isJanitorAlphaRequestShape(root)) {
    return { kind: 'janitor-alpha', requestContainer: root.userConfig, janitorRoot: root };
  }
  const seen = new WeakSet();
  const stack = [{ node: root, parent: null }];
  let best = null;
  let bestScore = 0;
  while (stack.length) {
    const frame = stack.pop();
    const node = frame.node;
    if (!isObject(node) || seen.has(node)) continue;
    seen.add(node);
    const chatShape = isCompletionMessageArray(node.messages);
    if (chatShape) {
      let container = null;
      let score = 0;
      if (modelNameFromContainer(node)) {
        container = node;
        score = 2;
      } else {
        for (let ancestor = frame.parent; ancestor; ancestor = ancestor.parent) {
          if (modelNameFromContainer(ancestor.node)) {
            container = ancestor.node;
            score = 1;
            break;
          }
        }
      }
      if (container && score > bestScore) {
        best = {
          kind: 'chat',
          messagesContainer: node,
          requestContainer: container,
          modelName: modelNameFromContainer(container),
        };
        bestScore = score;
        if (score === 2) return best;
      }
    }
    for (const key of Object.keys(node)) {
      if (key === 'messages' && chatShape) continue;
      const child = node[key];
      if (isObject(child)) stack.push({ node: child, parent: frame });
    }
  }
  return best;
}

// ---- janitor/envelope.js ----
// bridge-window: 5 s, long enough for one generation, too short to cross chats → docs/modules/janitor-transport.md#conversation-binding
const ROUTE_BINDING_FALLBACK_MS = 5_000;

// completion-url-pattern: copied verbatim from the optimizer, L55–56 → docs/modules/janitor-transport.md#request-gating
const COMPLETION_URL_PATTERN =
  /\/(?:chat\/)?completions?\b|\/(?:v1|api\/v1)\/responses\b|\/v1\/messages\b|:generateContent|\/generate(?:Content|_content)\b|\/generateAlpha\b|\/api\/v1\/chat\b/i;

const envelopeRegistry = new Map();
let latestCapture = null;

function token(value) {
  return String(value ?? '').trim();
}

function isObject(value) {
  return typeof value === 'object' && value !== null;
}

function normalizedRoutePath(pathname) {
  const path = String(pathname || '/').replace(/\/{2,}/g, '/');
  return path.length > 1 ? path.replace(/\/$/, '') : path;
}

function conversationIdentity() {
  const pathname = location.pathname;
  const match = /\/chats?\/([^/?#]+)/.exec(pathname);
  return match ? match[1] : pathname;
}

function parseRoute(userConfig) {
  const raw = token(userConfig.open_ai_reverse_proxy);
  if (!raw) return null;
  let parsed;
  try {
    parsed = new URL(raw, location.href);
  } catch {
    return null;
  }
  return { url: raw, host: parsed.hostname, path: normalizedRoutePath(parsed.pathname) };
}

function personaNameOf(data) {
  const direct = token(data.profile?.name);
  if (direct) return direct;
  const activeId = token(data.profile?.id);
  if (!activeId || !Array.isArray(data.profiles)) return '';
  const match = data.profiles.find((profile) => isObject(profile) && token(profile.id) === activeId);
  return token(match?.name);
}

// envelope-record: what /generateAlpha gives the later phases, nothing more → docs/modules/janitor-transport.md#envelope-record
function readEnvelope(data) {
  const userConfig = data.userConfig;
  const settings = userConfig.generation_settings;
  return {
    chatId: token(data.chat?.id),
    characterId: token(data.chat?.character_id),
    personaName: personaNameOf(data),
    generateType: data.generateType,
    prefill: {
      enabled: isObject(settings) && settings.prefill_enabled === true,
      text: isObject(settings) ? token(settings.prefill_text) : '',
    },
    route: parseRoute(userConfig),
    janitorRouterEnabled: userConfig.janitor_router_enabled === true,
    chatMessages: data.chatMessages.map((message, position) => ({
      position,
      isMain: isObject(message) && message.is_main === true,
      isBot: isObject(message) && message.is_bot === true,
      message: isObject(message) ? String(message.message ?? '') : '',
    })),
  };
}

// envelope-registry: keyed by URL identity and by chat id, in memory only → docs/modules/janitor-transport.md#conversation-binding
function recordEnvelope(data) {
  const envelope = readEnvelope(data);
  envelopeRegistry.set(conversationIdentity(), envelope);
  if (envelope.chatId) envelopeRegistry.set(envelope.chatId, envelope);
  latestCapture = { envelope, capturedAt: Date.now() };
  return envelope;
}

// latest-capture-bridge: covers the mid-flight URL mutation of a new chat → docs/modules/janitor-transport.md#conversation-binding
function currentEnvelope() {
  const exact = envelopeRegistry.get(conversationIdentity());
  if (exact) return exact;
  if (latestCapture && Date.now() - latestCapture.capturedAt < ROUTE_BINDING_FALLBACK_MS) {
    return latestCapture.envelope;
  }
  return null;
}

function looksLikeCompletionUrl(url) {
  return COMPLETION_URL_PATTERN.test(String(url || ''));
}

function isJanitorAlphaUrl(url) {
  return /\/generateAlpha\b/i.test(String(url || ''));
}

// route-match: same host, exact path or under the configured base → docs/modules/janitor-transport.md#request-gating
function routeMatches(url) {
  const route = currentEnvelope()?.route;
  if (!route) return false;
  let candidate;
  try {
    candidate = new URL(String(url || ''), location.href);
  } catch {
    return false;
  }
  if (candidate.hostname !== route.host) return false;
  const candidatePath = normalizedRoutePath(candidate.pathname);
  const exactPath = candidatePath === route.path;
  const routeIsBase = route.path === '/';
  const underConfiguredBase = route.path !== '/' && candidatePath.startsWith(`${route.path}/`);
  return (exactPath || routeIsBase || underConfiguredBase) && COMPLETION_URL_PATTERN.test(candidatePath);
}

// targeted-completion: learned route wins; the pattern is only the no-envelope fallback → docs/modules/janitor-transport.md#request-gating
function isTargetedCompletion(url) {
  if (isJanitorAlphaUrl(url)) return false;
  if (currentEnvelope()?.route) return routeMatches(url);
  return looksLikeCompletionUrl(url);
}

// ---- janitor/shell.js ----
let originalFetch = null;

function headerValue(headersInit, name) {
  try {
    return new Headers(headersInit || {}).get(name) || '';
  } catch {
    return '';
  }
}

// inspect-gate: non-empty JSON-looking POST body with a JSON or absent type → docs/modules/janitor-transport.md#request-gating
function shouldInspectRequest(resource, config, bodyText) {
  if (!bodyText) return false;
  if (bodyText.trimStart()[0] !== '{') return false;
  const isRequestObject = resource instanceof Request;
  const method = String(config?.method || (isRequestObject ? resource.method : 'GET')).toUpperCase();
  if (method !== 'POST') return false;
  const contentType = headerValue(config?.headers, 'content-type')
    || (isRequestObject ? resource.headers.get('content-type') || '' : '');
  return !contentType || /(?:application\/json|\+json)/i.test(contentType);
}

// response-wrapper: fresh stream forwards chunks verbatim; metadata copied on → docs/modules/janitor-transport.md#response-wrapper
function wrapResponse(response) {
  if (!response?.body) return response;
  const reader = response.body.getReader();
  const stream = new ReadableStream({
    async pull(controller) {
      const result = await reader.read();
      if (result.done) {
        controller.close();
        return;
      }
      controller.enqueue(result.value);
    },
    cancel(reason) {
      return reader.cancel(reason);
    },
  });
  const wrapped = new Response(stream, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
  for (const property of ['url', 'redirected', 'type']) {
    Object.defineProperty(wrapped, property, {
      configurable: true,
      enumerable: false,
      value: response[property],
    });
  }
  return wrapped;
}

// boot-capture: one capture per page, native check warns but never refuses → docs/modules/janitor-transport.md#boot-capture
function installTransport(transform) {
  if (originalFetch) return;
  originalFetch = window.fetch;
  if (!/\[native code\]/.test(Function.prototype.toString.call(originalFetch))) {
    console.warn(
      '[Manuscript] window.fetch was already wrapped before this script ran. '
        + 'Enable Tampermonkey Advanced → Experimental → Inject Mode: Instant, '
        + 'keep @run-at document-start, then hard reload.',
    );
  }
  window.fetch = async function (resource, config) {
    const isRequestObject = resource instanceof Request;
    const url = isRequestObject ? resource.url : String(resource);
    if (!isJanitorAlphaUrl(url) && !isTargetedCompletion(url)) {
      return originalFetch.call(window, resource, config);
    }
    let bodyText = '';
    try {
      if (config && typeof config.body === 'string') {
        bodyText = config.body;
      } else if (isRequestObject) {
        bodyText = await resource.clone().text();
      }
    } catch {
      bodyText = '';
    }
    if (!shouldInspectRequest(resource, config, bodyText)) {
      return originalFetch.call(window, resource, config);
    }
    let data;
    try {
      data = JSON.parse(bodyText);
    } catch {
      return originalFetch.call(window, resource, config);
    }
    const adapter = locateCompletionRequest(data);
    if (!adapter) return originalFetch.call(window, resource, config);
    if (adapter.kind === 'janitor-alpha') {
      recordEnvelope(data);
      return originalFetch.call(window, resource, config);
    }
    // transform-seam: phase-3 boundary; truthy means the body changed → docs/modules/janitor-transport.md#transform-seam
    const modified = transform(data, { ...currentEnvelope(), url, adapter });
    if (!modified) return wrapResponse(await originalFetch.call(window, resource, config));
    const outgoing = Object.assign({}, config || {}, { body: JSON.stringify(data) });
    return wrapResponse(await originalFetch.call(window, resource, outgoing));
  };
}

// ---- janitor/xhr-warning.js ----
let originalOpen = null;
let warned = false;

// xhr-detector: warn once on a completion-shaped open, then delegate → docs/modules/janitor-transport.md#xhr-detector
function installXhrWarning() {
  if (originalOpen) return;
  originalOpen = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function (method, url, ...rest) {
    if (!warned && looksLikeCompletionUrl(url)) {
      warned = true;
      console.warn(
        '[Manuscript] Janitor dispatched a completion through XMLHttpRequest. '
          + 'This build hooks fetch only; the XHR route runs on the degraded tier '
          + '(stop strings plus a trim at the next derivation, no live boundary).',
      );
    }
    return originalOpen.call(this, method, url, ...rest);
  };
}

// ---- janitor/main.js ----
// no-op-transform: the phase boundary; protocol logic replaces this → docs/modules/janitor-transport.md#transform-seam
installTransport(() => false);
installXhrWarning();

})();
